effect.shader:
/** SDF do retângulo arredondado (Inigo Quilez): negativo dentro, positivo fora. */
float sdfRetangulo(vec2 p, vec2 metade, float raio) {
    vec2 q = abs(p) - metade + vec2(raio);
    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - raio;
}

/** SDF da elipse por fórmula aproximada (precisa o bastante para pintar com AA). */
float sdfElipse(vec2 p, vec2 raio) {
    vec2 r = max(raio, vec2(1e-5));
    float d = length(p / r);
    // Projeta para pseudo-distância em unidades da menor dimensão: isso dá uma
    // gradiente aproveitável para o smoothstep da borda.
    return (d - 1.0) * min(r.x, r.y);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    vec2 p = (acScreenNorm - center) * vec2(acAspect, 1.0);
    vec2 metade = vec2(sizeX, sizeY) * 0.5;

    float d;
    if (kind == 1) {
        // elipse: raios independentes em x e y
        d = sdfElipse(p, metade);
    } else if (kind == 2) {
        // retângulo: canto arredondado opcional
        d = sdfRetangulo(p, metade, min(cornerRadius, min(metade.x, metade.y)));
    } else {
        // círculo: distância ao centro menos o raio
        d = length(p) - min(metade.x, metade.y);
    }

    float suave = max(softness, 1e-4);

    // Dentro da forma = 1, fora = 0, transição no raio `softness`.
    float dentro = 1.0 - smoothstep(-suave, suave, d);

    // Anel da borda: um smoothstep sobre a distância assinada entre -w e 0.
    float anel = smoothstep(outlineWidth + suave, outlineWidth - suave, d)
               - smoothstep(0.0 + suave, 0.0 - suave, d);
    anel = clamp(anel, 0.0, 1.0);

    float dentroPintado = dentro;
    if (invert) dentroPintado = 1.0 - dentro;

    // A forma pinta sobre a imagem; a borda por cima da forma.
    vec4 comPreench = mix(original, vec4(fillColor.rgb, fillColor.a), dentroPintado * fillColor.a);
    vec4 final_ = mix(comPreench, vec4(outlineColor.rgb, outlineColor.a), anel * outlineColor.a);

    fragColor = final_;
}
